                        link[13].second->setValue(nts::FALSE);
                        return (nts::TRUE);
                    }
                } else {
                    if (pin == 1) {
                        link[2].second->setValue(nts::FALSE);
                        return (nts::TRUE);
                    }
                    if (pin == 2) {
                        link[1].second->setValue(nts::TRUE);
                        return (nts::FALSE);
                    }
                    if (pin == 13) {
                        link[12].second->setValue(nts::FALSE);
                        return (nts::TRUE);
                    }
                    if (pin == 12) {
                        link[13].second->setValue(nts::TRUE);
                        return (nts::FALSE);
                    }
                }
