                if (pin == 2)
                    return (link[2].second->compute(link[2].first));
                if (pin == 13)
                    return (link[13].second->compute(link[13].first));
                if (pin == 12)
                    return (link[12].second->compute(link[12].first));
            }
        }
    }
    return (nts::Tristate::TRUE);
}

