        throw Errors("No pin matches", "C_4081");
    if (a == nts::Tristate::UNDEFINED || b == nts::Tristate::UNDEFINED)
        return (nts::Tristate::UNDEFINED);
    return (static_cast<nts::Tristate>(a && b));
}

